// Subject: Welcome to {_productName} — let's get you started

import {
  Body,
  Button,
  Column,
  Container,
  Head,
  Html,
  Img,
  Link,
  Preview,
  Row,
  Section,
  Tailwind,
  Text,
} from "jsx-email";

import { DefaultFonts } from "@/components/email/font-default";
import { emailAsset } from "@/components/email/email-assets";
import { defaultTheme } from "@/components/email/theme-default";
import { vercelTheme } from "@/components/email/theme-vercel";

interface ContentGridProps {
  columnCount?: 2 | 3;
  columns?: {
    iconUrl?: string;
    title: string;
    description: string;
  }[];
}

const ContentGridSection = ({
  columnCount = 2,
  columns = [
    { description: "Description for feature 1", title: "Feature 1" },
    { description: "Description for feature 2", title: "Feature 2" },
  ],
}: Omit<ContentGridProps, "theme">) => (
  <Section style={{ padding: "48px 0" }}>
    <Row>
      {columns.slice(0, columnCount).map((col, index) => (
        <Column
          key={`${col.title}-${index}`}
          style={{ padding: "24px", verticalAlign: "top" }}
        >
          {col.iconUrl ? (
            <Img
              src={col.iconUrl}
              alt={col.title}
              height={48}
              width={48}
              style={{
                marginBottom: "24px",
                objectFit: "contain",
              }}
            />
          ) : null}
          <Text
            style={{
              color: defaultTheme.colorText,
              fontSize: defaultTheme.fontSizeLg,
              fontWeight: defaultTheme.fontWeightMedium,
              marginBottom: "8px",
            }}
          >
            {col.title}
          </Text>
          <Text
            style={{
              color: defaultTheme.colorTextMuted,
              fontSize: defaultTheme.fontSizeBase,
              lineHeight: 1.4,
            }}
          >
            {col.description}
          </Text>
        </Column>
      ))}
    </Row>
  </Section>
);

interface CTABannerProps {
  heading?: string;
  subtext?: string;
  ctaLabel?: string;
  ctaHref?: string;
  variant?: "filled" | "outline";
}

const CTABannerSection = ({
  heading = "Get Started",
  subtext = "Join thousands of happy users.",
  ctaLabel = "Get Started",
  ctaHref = "#",
  variant = "filled",
}: Omit<CTABannerProps, "theme">) => {
  const isFilled = variant === "filled";

  return (
    <Section
      style={{
        backgroundColor: isFilled ? defaultTheme.colorPrimary : "transparent",
        border: isFilled ? "none" : `1px solid ${defaultTheme.colorBorder}`,
        borderRadius: defaultTheme.borderRadius,
        padding: "32px",
      }}
    >
      <Container style={{ textAlign: "center" }}>
        <Text
          style={{
            color: isFilled
              ? defaultTheme.colorPrimaryForeground
              : defaultTheme.colorText,
            fontSize: defaultTheme.fontSizeXl,
            fontWeight: defaultTheme.fontWeightMedium,
            marginBottom: "8px",
            textAlign: "center",
          }}
        >
          {heading}
        </Text>
        <Text
          style={{
            color: isFilled
              ? defaultTheme.colorPrimaryForeground
              : defaultTheme.colorTextMuted,
            fontSize: defaultTheme.fontSizeBase,
            marginBottom: "24px",
            opacity: isFilled ? 0.9 : 1,
            textAlign: "center",
          }}
        >
          {subtext}
        </Text>
        {ctaLabel && ctaHref ? (
          <Button
            href={ctaHref}
            width={160}
            height={40}
            style={{
              backgroundColor: isFilled
                ? defaultTheme.colorPrimaryForeground
                : defaultTheme.colorPrimary,
              borderRadius: defaultTheme.button.primary.borderRadius,
              color: isFilled
                ? defaultTheme.colorPrimary
                : defaultTheme.colorPrimaryForeground,
              display: "block",
              fontSize: defaultTheme.button.primary.fontSize,
              fontWeight: defaultTheme.button.primary.fontWeight,
              height: "auto",
              paddingBottom: defaultTheme.button.primary.paddingY,
              paddingLeft: defaultTheme.button.primary.paddingX,
              paddingRight: defaultTheme.button.primary.paddingX,
              paddingTop: defaultTheme.button.primary.paddingY,
              textAlign: "center",
              textDecoration: "none",
              width: "auto",
            }}
          >
            {ctaLabel}
          </Button>
        ) : null}
      </Container>
    </Section>
  );
};

interface FooterProps {
  companyName?: string;
  address?: string;
  links?: { label: string; href: string }[];
  unsubscribeHref?: string;
}

const FooterSection = ({
  companyName = "Acme",
  address = "123 Main St, San Francisco, CA",
  links = [
    { href: "#", label: "Privacy" },
    { href: "#", label: "Terms" },
  ],
  unsubscribeHref = "#",
}: Omit<FooterProps, "theme">) => (
  <Section
    style={{
      borderTop: `1px solid ${defaultTheme.colorBorder}`,
      paddingBottom: "24px",
      paddingTop: "48px",
    }}
  >
    <Text
      style={{
        color: defaultTheme.colorTextMuted,
        fontSize: defaultTheme.fontSizeSm,
        lineHeight: 1.5,
        marginBottom: "8px",
      }}
    >
      © {new Date().getFullYear()} {companyName}. All rights reserved.
    </Text>
    {address ? (
      <Text
        style={{
          color: defaultTheme.colorTextMuted,
          fontSize: defaultTheme.fontSizeSm,
          lineHeight: 1.5,
          marginBottom: "8px",
        }}
      >
        {address}
      </Text>
    ) : null}
    <Row>
      {links.map((link) => (
        <Column key={`${link.href}-${link.label}`}>
          <Link
            href={link.href}
            style={{
              color: defaultTheme.colorTextMuted,
              fontSize: defaultTheme.fontSizeSm,
              marginRight: "24px",
              textDecoration: "none",
            }}
          >
            {link.label}
          </Link>
        </Column>
      ))}
    </Row>
    <Text style={{ fontSize: defaultTheme.fontSizeSm, marginTop: "24px" }}>
      <Link
        href={unsubscribeHref}
        style={{
          color: defaultTheme.colorTextMuted,
          textDecoration: "underline",
        }}
      >
        Unsubscribe
      </Link>
    </Text>
  </Section>
);

type HeroVariant = "default" | "slanted-left" | "slanted-right";

interface HeroProps {
  heading?: string;
  subheading?: string;
  ctaLabel?: string;
  ctaHref?: string;
  align?: "left" | "center";
  variant?: HeroVariant;
}

const HeroSection = ({
  align = "center",
  ctaHref = "#",
  ctaLabel = "Get Started",
  heading = "Welcome",
  subheading = "Get started with your account",
  variant = "default",
}: Omit<HeroProps, "theme">) => {
  void variant;
  const alignStyle =
    align === "center"
      ? { textAlign: "center" as const }
      : { textAlign: "left" as const };

  return (
    <Section
      style={{
        backgroundColor: defaultTheme.colorBackground,
        padding: "48px 0",
      }}
    >
      <Container
        style={{ maxWidth: defaultTheme.containerWidth, ...alignStyle }}
      >
        <Text
          style={{
            color: defaultTheme.colorText,
            fontSize: defaultTheme.fontSizeHeading,
            fontWeight: defaultTheme.fontWeightBold,
            lineHeight: 1.3,
            margin: 0,
            ...alignStyle,
          }}
        >
          {heading}
        </Text>
        <Text
          style={{
            color: defaultTheme.colorTextMuted,
            fontSize: defaultTheme.fontSizeLg,
            lineHeight: 1.5,
            marginBottom: "32px",
            marginTop: "24px",
            ...alignStyle,
          }}
        >
          {subheading}
        </Text>
        {ctaLabel && ctaHref ? (
          <Section style={alignStyle}>
            <Button
              href={ctaHref}
              width={160}
              height={40}
              style={{
                backgroundColor: defaultTheme.button.primary.backgroundColor,
                borderRadius: defaultTheme.button.primary.borderRadius,
                color: defaultTheme.button.primary.color,
                display: "inline-block",
                fontSize: defaultTheme.button.primary.fontSize,
                fontWeight: defaultTheme.button.primary.fontWeight,
                height: "auto",
                paddingBottom: defaultTheme.button.primary.paddingY,
                paddingLeft: defaultTheme.button.primary.paddingX,
                paddingRight: defaultTheme.button.primary.paddingX,
                paddingTop: defaultTheme.button.primary.paddingY,
                textDecoration: "none",
                width: "auto",
              }}
            >
              {ctaLabel}
            </Button>
          </Section>
        ) : null}
      </Container>
    </Section>
  );
};

interface LogoHeaderProps {
  logoUrl?: string;
  logoAlt?: string;
  logoWidth?: number;
  links?: { label: string; href: string }[];
}

const LogoHeaderSection = ({
  logoUrl,
  logoAlt = "Logo",
  logoWidth = 120,
  links = [],
}: Omit<LogoHeaderProps, "theme">) => (
  <Section style={{ paddingBottom: "24px", paddingTop: "24px" }}>
    <Row>
      <Column style={{ textAlign: "left" }}>
        {logoUrl ? (
          <Img
            src={logoUrl}
            alt={logoAlt}
            width={logoWidth}
            style={{ display: "block", height: "auto", maxWidth: logoWidth }}
          />
        ) : (
          <Text
            style={{
              color: defaultTheme.colorText,
              fontFamily: defaultTheme.fontFamily,
              fontSize: defaultTheme.fontSizeBase,
              fontWeight: defaultTheme.fontWeightBold,
            }}
          >
            {logoAlt}
          </Text>
        )}
      </Column>
      {links.length > 0 ? (
        <Column style={{ textAlign: "right" }}>
          {links.map((link) => (
            <Link
              key={`${link.href}-${link.label}`}
              href={link.href}
              style={{
                color: defaultTheme.colorTextMuted,
                fontSize: defaultTheme.fontSizeSm,
                marginLeft: "16px",
                textDecoration: "none",
              }}
            >
              {link.label}
            </Link>
          ))}
        </Column>
      ) : null}
    </Row>
  </Section>
);

interface Props {
  _firstName?: string;
  _productName?: string;
  ctaHref?: string;
  _senderName?: string;
  _senderTitle?: string;
  _senderAvatarUrl?: string;
}

export const OnboardingVercel = ({
  _firstName = "there",
  _productName = "Vercel",
  ctaHref = "https://vercel.com",
  _senderName = "Vercel Team",
  _senderTitle,
  _senderAvatarUrl,
}: Props) => {
  void _senderAvatarUrl;
  void _senderTitle;

  return (
    <Html>
      <Head>
        <DefaultFonts />
      </Head>
      <Preview>
        Welcome to {_productName}, {_firstName}
      </Preview>
      <Tailwind>
        <Body
          style={{
            backgroundColor: vercelTheme.colorBackground,
            fontFamily: vercelTheme.fontFamily,
            margin: 0,
          }}
        >
          <Container
            style={{ maxWidth: vercelTheme.containerWidth, padding: "32px" }}
          >
            <LogoHeaderSection logoAlt={_productName} />

            <HeroSection
              heading={`Welcome, ${_firstName}`}
              subheading={`You're now part of the fastest-growing platform for frontend developers.`}
              ctaLabel="Deploy your first project"
              ctaHref={ctaHref}
              align="left"
            />

            <ContentGridSection
              columnCount={3}
              columns={[
                {
                  description: "Deploy to the edge in seconds.",
                  title: "Global Edge",
                },
                {
                  description: "Every git push gets a unique URL.",
                  title: "Preview Deploys",
                },
                {
                  description: "Connect your own domain.",
                  title: "Custom Domains",
                },
              ]}
            />

            <CTABannerSection
              heading="Start deploying"
              subtext="Ready to ship to production?"
              ctaLabel="Create a Project"
              ctaHref={ctaHref}
            />

            <Section
              style={{
                paddingBottom: vercelTheme.spacingBase,
                paddingTop: vercelTheme.spacingBase,
              }}
            >
              <Text
                style={{
                  color: vercelTheme.colorTextMuted,
                  fontSize: vercelTheme.fontSizeSm,
                }}
              >
                Sent by {_senderName}
              </Text>
            </Section>

            <FooterSection companyName={_productName} />
          </Container>
        </Body>
      </Tailwind>
    </Html>
  );
};

OnboardingVercel.PreviewProps = {
  _firstName: "Aniket",
  _productName: "Vercel",
  _senderAvatarUrl: emailAsset("avatars/avatar-1.jpg"),
  _senderName: "Vercel Team",
  _senderTitle: "Team",
  ctaHref: "https://vercel.com/dashboard",
} satisfies Props;

const ASSET_ORIGIN = "https://www.emailcn.run";
const ICONS8_ORIGIN = "https://img.icons8.com";
const UNSPLASH_ORIGIN = "https://images.unsplash.com";

const portraitIds = [
  "photo-1500648767791-00dcc994a43e",
  "photo-1507003211169-0a1dd7228f2d",
  "photo-1494790108377-be9c29b29330",
  "photo-1438761681033-6461ffad8d80",
  "photo-1534528741775-53994a69daeb",
  "photo-1506794778202-cad84cf45f1c",
] as const;

const productIds = [
  "photo-1521572163474-6864f9cf17ab",
  "photo-1503341504253-dff4815485f1",
  "photo-1576566588028-4147f3842f27",
  "photo-1562157873-818bc0726f68",
] as const;

const socialIconSlugs = {
  discord: "discord-logo",
  facebook: "facebook-new",
  github: "github",
  instagram: "instagram-new",
  linkedin: "linkedin",
  slack: "slack-new",
  x: "twitterx--v1",
  youtube: "youtube-play",
} as const;

const brandIconSlugs = [
  [/(?:btc|bitcoin)/i, "bitcoin--v1"],
  [/(?:eth|ethereum)/i, "ethereum"],
  [/visa/i, "visa"],
  [/mastercard/i, "mastercard-logo"],
  [/apple-pay/i, "apple-pay"],
  [/google-pay/i, "google-pay"],
  [/klarna/i, "klarna"],
  [/stripe/i, "stripe"],
  [/fedex/i, "fedex"],
  [/north-face/i, "the-north-face"],
] as const;

const hashString = (value: string) => {
  let hash = 7;

  for (const character of value) {
    hash = (hash * 31 + (character.codePointAt(0) ?? 0)) % 2_147_483_647;
  }

  return hash;
};

const getDimensions = (path: string) => {
  if (/teams\/member-\d+-lg/i.test(path)) {
    return [800, 560] as const;
  }
  if (/teams\/member-\d+/i.test(path)) {
    return [600, 600] as const;
  }
  if (/(?:avatar|user|headshot)/i.test(path)) {
    return [160, 160] as const;
  }
  if (/(?:logo|insignia)/i.test(path)) {
    return [320, 96] as const;
  }
  if (/(?:badge-app|badge-google)/i.test(path)) {
    return [260, 80] as const;
  }
  if (/(?:icon|btc|eth)/i.test(path)) {
    return [64, 64] as const;
  }
  if (/(?:portrait|member|team)/i.test(path)) {
    return [600, 800] as const;
  }
  if (/(?:square|product|shopping-cart)/i.test(path)) {
    return [700, 700] as const;
  }
  if (/(?:hero|footer|background|bg-|overlay|full-width)/i.test(path)) {
    return [1200, 700] as const;
  }
  if (/(?:strip|landscape|bento|category-preview)/i.test(path)) {
    return [800, 520] as const;
  }

  return [800, 600] as const;
};

const getSeed = (path: string) =>
  `emailcn-${path
    .replace(/\.[^.]+$/, "")
    .replaceAll(/[^a-z0-9]+/gi, "-")
    .replaceAll(/^-|-$/g, "")
    .toLowerCase()}`;

const getIndexedAsset = (path: string, assets: readonly string[]) => {
  const explicitIndex = path.match(
    /(?:member|avatar|product-list|shopping-cart)-(\d+)/i
  )?.[1];
  const index = explicitIndex
    ? Number.parseInt(explicitIndex, 10) - 1
    : hashString(path);

  return assets[((index % assets.length) + assets.length) % assets.length];
};

const getUnsplashAsset = (id: string, width: number, height: number) =>
  `${UNSPLASH_ORIGIN}/${id}?auto=format&fit=crop&w=${width}&h=${height}&q=80`;

const getIcons8Asset = (
  slug: string,
  {
    color,
    style = "ios-filled",
  }: {
    color?: string;
    style?: "color" | "ios" | "ios-filled";
  } = {}
) =>
  color
    ? `${ICONS8_ORIGIN}/${style}/50/${color}/${slug}.png`
    : `${ICONS8_ORIGIN}/${style}/50/${slug}.png`;

const getStoreBadgeAsset = (path: string) => {
  if (/badge-app-store/i.test(path)) {
    return "https://developer.apple.com/assets/elements/badges/download-on-the-app-store.svg";
  }
  if (/badge-google-play/i.test(path)) {
    return "https://play.google.com/intl/en_us/badges/static/images/badges/en_badge_web_generic.png";
  }
};

const getSocialIconAsset = (path: string) => {
  const isLight = /(?:-light|check-white)/i.test(path);
  const foreground = isLight ? "FFFFFF" : "111827";

  for (const [name, slug] of Object.entries(socialIconSlugs)) {
    if (new RegExp(`(?:^|[-/])${name}(?:[-.]|$)`, "i").test(path)) {
      return getIcons8Asset(slug, { color: foreground });
    }
  }
};

const getUtilityIconAsset = (path: string) => {
  const isLight = /(?:-light|check-white)/i.test(path);
  const foreground = isLight ? "FFFFFF" : "111827";

  if (/star-half/i.test(path)) {
    return getIcons8Asset("star-half-empty", { color: "374151" });
  }
  if (/star-solid/i.test(path)) {
    return getIcons8Asset("star--v1", { color: "374151" });
  }
  if (/edit/i.test(path)) {
    return getIcons8Asset("edit--v1", {
      color: "4F46E5",
      style: "ios",
    });
  }
  if (/arrow-right/i.test(path)) {
    return getIcons8Asset("long-arrow-right--v1", {
      color: "4F46E5",
      style: "ios",
    });
  }
  if (/chevron-right/i.test(path)) {
    return getIcons8Asset("chevron-right", {
      color: "4F46E5",
      style: "ios",
    });
  }
  if (/check/i.test(path)) {
    return getIcons8Asset("checkmark--v1", { color: foreground });
  }
};

const getBrandIconAsset = (path: string) => {
  const match = brandIconSlugs.find(([pattern]) => pattern.test(path));

  return match
    ? getIcons8Asset(match[1], {
        style: "color",
      })
    : undefined;
};

const getWordmarkAsset = (path: string) => {
  const isLight = /light/i.test(path);
  const background = isLight ? "030712" : "FFFFFF";
  const foreground = isLight ? "FFFFFF" : "111827";

  return `https://placehold.co/320x96/${background}/${foreground}.png?text=EMAILCN`;
};

const getIconAsset = (path: string) =>
  getStoreBadgeAsset(path) ??
  getSocialIconAsset(path) ??
  getUtilityIconAsset(path) ??
  getBrandIconAsset(path);

export const emailAsset = (path: string) => {
  const normalizedPath = path.replace(/^\/+/, "");

  if (
    normalizedPath === "bento-grids/trend.png" ||
    normalizedPath === "bento-grids/trend-sm.png"
  ) {
    return `${ASSET_ORIGIN}/email-assets/${normalizedPath}`;
  }

  const iconAsset = getIconAsset(normalizedPath);
  if (iconAsset) {
    return iconAsset;
  }

  const seed = getSeed(normalizedPath);
  const [width, height] = getDimensions(normalizedPath);

  if (/teams\/hero/i.test(normalizedPath)) {
    return getUnsplashAsset("photo-1521737711867-e3b97375f902", width, height);
  }

  if (/(?:avatar|user|headshot|member|team)/i.test(normalizedPath)) {
    return getUnsplashAsset(
      getIndexedAsset(normalizedPath, portraitIds),
      width,
      height
    );
  }

  if (/products\/shoe/i.test(normalizedPath)) {
    return getUnsplashAsset("photo-1542291026-7eec264c27ff", width, height);
  }

  if (/products\/phone/i.test(normalizedPath)) {
    return getUnsplashAsset("photo-1511707171634-5f897ff02aa9", width, height);
  }

  if (
    /(?:product-detail|product-lists|products\/product|shopping-cart)/i.test(
      normalizedPath
    )
  ) {
    return getUnsplashAsset(
      getIndexedAsset(normalizedPath, productIds),
      width,
      height
    );
  }

  if (/(?:trend|chart)/i.test(normalizedPath)) {
    return `${ASSET_ORIGIN}/email-assets/bento-grids/trend.png`;
  }

  if (/(?:emailcn|maizzle|logo|insignia)/i.test(normalizedPath)) {
    return getWordmarkAsset(normalizedPath);
  }

  return `https://picsum.photos/seed/${encodeURIComponent(
    seed
  )}/${width}/${height}.jpg`;
};
